#include <iostream>
#include <vector>
struct Item{int key;int original;};
int main(){
 std::vector<Item>a{{2,0},{1,1},{2,2},{1,3}};
 for(std::size_t i=1;i<a.size();++i){
  Item saved=a[i];std::size_t j=i;
  while(j>0&&saved.key<a[j-1].key){a[j]=a[j-1];--j;}
  a[j]=saved;
 }
 for(const Item&x:a)std::cout<<x.key<<':'<<x.original<<' ';
 std::cout<<'\n';
}

#include <iostream>
#include <vector>
int main(){
 std::vector<int>a{3,1,2};
 for(std::size_t i=0;i<a.size();++i){
  std::size_t best=i;
  for(std::size_t j=i+1;j<a.size();++j)if(a[j]<a[best])best=j;
  int saved=a[i];a[i]=a[best];a[best]=saved;
 }
 for(int x:a)std::cout<<x<<' ';
 std::cout<<'\n';
}

