#include <vector>
int main(){std::vector<int>a{3,1,2,1};
 for(std::size_t end=a.size();end>1;--end){bool swapped=false;
  for(std::size_t j=1;j<end;++j)if(a[j]<a[j-1]){int x=a[j];a[j]=a[j-1];a[j-1]=x;swapped=true;}
  if(!swapped)break;
 }
 for(std::size_t i=0;i<a.size();++i){if(i)std::cout<<' ';std::cout<<a[i];}std::cout<<'\n';
}

